create or replace function public._adm_duty_view(_school uuid) returns boolean language sql stable security definer set search_path=public as $$ select case when _perm_owner(auth.uid(), school_org(_school)) then _adm_lead(_school) else _ws_view(_school,'duty_rosters') end $$;
create or replace function public._adm_duty_manage(_school uuid) returns boolean language sql stable security definer set search_path=public as $$ select case when _perm_owner(auth.uid(), school_org(_school)) then _adm_lead(_school) else _ws_ok(_school,'duty_rosters','edit') end $$;
create or replace function public._adm_duty_setup(_school uuid) returns boolean language sql stable security definer set search_path=public as $$ select case when _perm_owner(auth.uid(), school_org(_school)) then _adm_principal(_school) else _ws_ok(_school,'duty_setup','edit') end $$;
create or replace function public._adm_duty_setup_view(_school uuid) returns boolean language sql stable security definer set search_path=public as $$ select case when _perm_owner(auth.uid(), school_org(_school)) then _adm_principal(_school) else _ws_view(_school,'duty_setup') end $$;